function [v, faults, idx] = kpi_fault_raised(faults, idx, ni, mask)
%KPI_FAULT_RAISED  Whether the flight software's fault word had a flag of the mask set at any of the window's samples idx[0..ni]: 1 raised, 0 not
%   (faults the word at each sample, mask the bits the fault should raise: a bus fault at a device is meant to set its driver's flag).
%   length: 64
%   faults: inout int[*] (passed a whole number)
%   idx: inout int[*] (passed a whole number)
%   ni: int (passed a whole number)
%   mask: int (passed a whole number)
%   returns v: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    v = 0;
    v = 0;
    for i = (0):((ni) - 1)
        if (bitand(faults((idx((i) + 1)) + 1), mask) ~= 0)
            v = 1;
        end
    end
end
